//! Data exchanged between the backend and the UI.

use serde::{Deserialize, Serialize};

use crate::config::{ProviderKind, SearchEngine};
use crate::permissions::{PermissionLevel, ToolRisk};

/// Identifiers are UUID strings generated by the backend.
pub type Id = String;

/// A model on a specific provider.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct ModelRef {
    pub provider: String,
    pub model: String,
}

impl ModelRef {
    pub fn new(provider: impl Into<String>, model: impl Into<String>) -> Self {
        Self { provider: provider.into(), model: model.into() }
    }

    /// `provider/model`, used as a stable key in the UI.
    pub fn key(&self) -> String {
        format!("{}/{}", self.provider, self.model)
    }

    /// Parses a `provider/model` key (the model part may itself contain `/`).
    pub fn parse_key(key: &str) -> Option<Self> {
        let (provider, model) = key.split_once('/')?;
        if provider.is_empty() || model.is_empty() {
            return None;
        }
        Some(Self::new(provider, model))
    }

    /// Short human label: the model name without registry prefixes.
    pub fn short_label(&self) -> String {
        crate::util::short_model_name(&self.model)
    }
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, Hash)]
#[serde(rename_all = "lowercase")]
pub enum Role {
    System,
    User,
    Assistant,
}

impl Role {
    pub fn as_str(self) -> &'static str {
        match self {
            Role::System => "system",
            Role::User => "user",
            Role::Assistant => "assistant",
        }
    }

    pub fn parse(s: &str) -> Self {
        match s {
            "system" => Role::System,
            "assistant" => Role::Assistant,
            _ => Role::User,
        }
    }
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, Default)]
#[serde(rename_all = "snake_case")]
pub enum MessageStatus {
    /// Waiting for the model to start (or queued behind approvals).
    #[default]
    Pending,
    Streaming,
    Complete,
    Error,
    Cancelled,
}

impl MessageStatus {
    pub fn as_str(self) -> &'static str {
        match self {
            MessageStatus::Pending => "pending",
            MessageStatus::Streaming => "streaming",
            MessageStatus::Complete => "complete",
            MessageStatus::Error => "error",
            MessageStatus::Cancelled => "cancelled",
        }
    }

    pub fn parse(s: &str) -> Self {
        match s {
            "streaming" => MessageStatus::Streaming,
            "complete" => MessageStatus::Complete,
            "error" => MessageStatus::Error,
            "cancelled" => MessageStatus::Cancelled,
            _ => MessageStatus::Pending,
        }
    }

    pub fn is_active(self) -> bool {
        matches!(self, MessageStatus::Pending | MessageStatus::Streaming)
    }
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, Default)]
#[serde(rename_all = "snake_case")]
pub enum ToolCallStatus {
    #[default]
    Pending,
    AwaitingApproval,
    Running,
    Success,
    Error,
    Denied,
}

impl ToolCallStatus {
    pub fn is_finished(self) -> bool {
        matches!(self, ToolCallStatus::Success | ToolCallStatus::Error | ToolCallStatus::Denied)
    }
}

/// One tool invocation made by an assistant, with its result.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Default)]
pub struct ToolCallPart {
    /// Provider supplied call id (synthesised for providers without ids).
    pub id: String,
    /// Tool name as the model called it (e.g. `bash`, `mcp__github__search`).
    pub name: String,
    /// Raw JSON arguments.
    pub arguments: String,
    pub status: ToolCallStatus,
    /// Text returned to the model.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub result: Option<String>,
    /// Structured data for richer UI rendering (e.g. search results).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub data: Option<serde_json::Value>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub risk: Option<ToolRisk>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub duration_ms: Option<u64>,
}

impl ToolCallPart {
    pub fn arguments_json(&self) -> serde_json::Value {
        serde_json::from_str(&self.arguments).unwrap_or(serde_json::Value::Null)
    }
}

/// A piece of message content. Assistant turns interleave text, reasoning and
/// tool calls in the order they were produced.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Part {
    Text {
        text: String,
    },
    Reasoning {
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        duration_ms: Option<u64>,
    },
    ToolCall(ToolCallPart),
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum DeltaKind {
    Text,
    Reasoning,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, Default)]
pub struct Usage {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub prompt_tokens: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub completion_tokens: Option<u64>,
}

impl Usage {
    pub fn add(&mut self, other: Usage) {
        fn sum(a: Option<u64>, b: Option<u64>) -> Option<u64> {
            match (a, b) {
                (None, None) => None,
                (a, b) => Some(a.unwrap_or(0) + b.unwrap_or(0)),
            }
        }
        // Prompt tokens of later rounds include the earlier context, so keep the
        // largest prompt and sum completions.
        self.prompt_tokens = match (self.prompt_tokens, other.prompt_tokens) {
            (Some(a), Some(b)) => Some(a.max(b)),
            (a, b) => a.or(b),
        };
        self.completion_tokens = sum(self.completion_tokens, other.completion_tokens);
    }
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, Default)]
#[serde(rename_all = "snake_case")]
pub enum AttachmentKind {
    Image,
    Text,
    Document,
    #[default]
    Binary,
}

impl AttachmentKind {
    pub fn as_str(self) -> &'static str {
        match self {
            AttachmentKind::Image => "image",
            AttachmentKind::Text => "text",
            AttachmentKind::Document => "document",
            AttachmentKind::Binary => "binary",
        }
    }

    pub fn parse(s: &str) -> Self {
        match s {
            "image" => AttachmentKind::Image,
            "text" => AttachmentKind::Text,
            "document" => AttachmentKind::Document,
            _ => AttachmentKind::Binary,
        }
    }
}

