#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Message {
    pub id: Id,
    pub chat_id: Id,
    #[serde(default)]
    pub parent_id: Option<Id>,
    pub role: Role,
    #[serde(default)]
    pub parts: Vec<Part>,
    #[serde(default)]
    pub attachments: Vec<AttachmentMeta>,
    #[serde(default)]
    pub model: Option<ModelRef>,
    /// Shared by all responses of one ensemble request.
    #[serde(default)]
    pub group_id: Option<Id>,
    /// This response merges the other responses in its group.
    #[serde(default)]
    pub synthesis: bool,
    #[serde(default)]
    pub status: MessageStatus,
    #[serde(default)]
    pub error: Option<String>,
    #[serde(default)]
    pub usage: Option<Usage>,
    pub created_at: i64,
    #[serde(default)]
    pub duration_ms: Option<u64>,
    /// Time to first token.
    #[serde(default)]
    pub ttft_ms: Option<u64>,
}

impl Message {
    /// Concatenated visible text.
    pub fn text(&self) -> String {
        let mut out = String::new();
        for part in &self.parts {
            if let Part::Text { text } = part {
                if !out.is_empty() && !out.ends_with('\n') {
                    out.push_str("\n\n");
                }
                out.push_str(text);
            }
        }
        out
    }

    /// Appends streamed text. Both the backend and the UI apply deltas with this
    /// function so their copies of a message stay identical.
    pub fn push_delta(&mut self, kind: DeltaKind, delta: &str) {
        if delta.is_empty() {
            return;
        }
        match (self.parts.last_mut(), kind) {
            (Some(Part::Text { text }), DeltaKind::Text) => text.push_str(delta),
            (Some(Part::Reasoning { text, .. }), DeltaKind::Reasoning) => text.push_str(delta),
            (_, DeltaKind::Text) => self.parts.push(Part::Text { text: delta.to_string() }),
            (_, DeltaKind::Reasoning) => {
                self.parts.push(Part::Reasoning { text: delta.to_string(), duration_ms: None })
            }
        }
    }

    pub fn tool_call_mut(&mut self, call_id: &str) -> Option<&mut ToolCallPart> {
        self.parts.iter_mut().find_map(|p| match p {
            Part::ToolCall(tc) if tc.id == call_id => Some(tc),
            _ => None,
        })
    }

    pub fn is_active(&self) -> bool {
        self.status.is_active()
    }
}

/// Per-chat generation settings.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Default)]
#[serde(default)]
pub struct ChatSettings {
    /// One model for a normal chat; several for an ensemble.
    pub models: Vec<ModelRef>,
    /// Merge ensemble responses into one answer.
    pub synthesize: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub synthesizer: Option<ModelRef>,
    /// Offer built-in + MCP tools.
    pub tools: bool,
    /// Offer the `web_search` / `fetch_url` tools.
    pub web_search: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub temperature: Option<f32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub max_tokens: Option<u32>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reasoning_effort: Option<String>,
    /// Overrides the global permission level for this chat.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub permission: Option<PermissionLevel>,
}

impl ChatSettings {
    pub fn is_ensemble(&self) -> bool {
        self.models.len() > 1
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Chat {
    pub id: Id,
    pub title: String,
    #[serde(default)]
    pub system_prompt: Option<String>,
    #[serde(default)]
    pub settings: ChatSettings,
    #[serde(default)]
    pub pinned: bool,
    #[serde(default)]
    pub archived: bool,
    /// The leaf of the currently displayed branch.
    #[serde(default)]
    pub current_leaf: Option<Id>,
    pub created_at: i64,
    pub updated_at: i64,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ChatSummary {
    pub id: Id,
    pub title: String,
    pub pinned: bool,
    pub archived: bool,
    pub created_at: i64,
    pub updated_at: i64,
    /// First models of the chat (for the sidebar badge).
    #[serde(default)]
    pub models: Vec<ModelRef>,
    /// Snippet of the matching text when searching.
    #[serde(default)]
    pub snippet: Option<String>,
}

impl From<&Chat> for ChatSummary {
    fn from(c: &Chat) -> Self {
        Self {
            id: c.id.clone(),
            title: c.title.clone(),
            pinned: c.pinned,
            archived: c.archived,
            created_at: c.created_at,
            updated_at: c.updated_at,
            models: c.settings.models.clone(),
            snippet: None,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ChatDetail {
    pub chat: Chat,
    pub messages: Vec<Message>,
}

/// A model offered by a provider.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ModelInfo {
    pub provider: String,
    pub provider_name: String,
    pub provider_kind: ProviderKind,
    pub id: String,
    #[serde(default)]
    pub vision: Option<bool>,
    #[serde(default)]
    pub tools: Option<bool>,
    #[serde(default)]
    pub reasoning: Option<bool>,
    #[serde(default)]
    pub size_bytes: Option<u64>,
}

impl ModelInfo {
    pub fn model_ref(&self) -> ModelRef {
        ModelRef::new(&self.provider, &self.id)
    }
}

